import numpy as np, pickle, glob, json
for f in sorted(glob.glob('*.npz')):
    try:
        with np.load(f, allow_pickle=False) as z:
            print(f, {k: (v.shape, v.dtype, v.ravel()[:10]) for k,v in z.items()})
    except Exception as e:
        print(f, 'ERR', e)
